<?php
/**
 * Plugin Name: Ninja Updater MU Snippet Loader
 * Description: Loads selected Ninja Updater .mu.php snippets before normal plugins.
 *
 * Automatically generated and maintained by Ninja Updater.
 * Do not edit this file manually.
 */

defined( 'ABSPATH' ) || exit;

$ninja_updater_plugin = 'ninja-updater/ninja-updater.php';
$ninja_updater_dir    = 'ninja-updater';

/*
 * Only run while Ninja Updater is active.
 *
 * MU plugins run regardless of the normal plugin activation state,
 * so explicitly check whether Ninja Updater itself is active.
 */
$active_plugins = (array) get_option( 'active_plugins', array() );

$is_active = in_array(
    $ninja_updater_plugin,
    $active_plugins,
    true
);

/*
 * Network-activated multisite support.
 */
if ( ! $is_active && is_multisite() ) {

    $network_plugins = (array) get_site_option(
        'active_sitewide_plugins',
        array()
    );

    $is_active = isset(
        $network_plugins[ $ninja_updater_plugin ]
    );
}

if ( ! $is_active ) {
    return;
}


/*
 * Selected snippets.
 */
$selected_snippets = get_option(
    'ninja_updater_selected_snippets',
    array()
);

if ( ! is_array( $selected_snippets ) ) {
    return;
}


/*
 * Snippet directory.
 */
$snippets_dir =
    trailingslashit( WP_PLUGIN_DIR )
    . $ninja_updater_dir
    . '/inc/snippets/';

$snippets_realpath = realpath( $snippets_dir );

if ( false === $snippets_realpath ) {
    return;
}

$snippets_realpath = trailingslashit(
    wp_normalize_path( $snippets_realpath )
);


/*
 * Load selected *.mu.php snippets.
 */
foreach ( $selected_snippets as $snippet ) {

    $snippet = ltrim(
        trim( (string) $snippet ),
        "/\\"
    );

    if ( '' === $snippet ) {
        continue;
    }

    /*
     * Only MU snippets are allowed through this loader.
     */
    if (
        strlen( $snippet ) < 7 ||
        substr( $snippet, -7 ) !== '.mu.php'
    ) {
        continue;
    }

    /*
     * Basic traversal protection.
     */
    if (
        false !== strpos( $snippet, '../' ) ||
        false !== strpos( $snippet, '..\\' )
    ) {
        continue;
    }

    $path = $snippets_dir . $snippet;

    if ( ! is_file( $path ) || ! is_readable( $path ) ) {
        continue;
    }

    /*
     * Verify the resolved file still lives inside /inc/snippets/.
     */
    $real_path = realpath( $path );

    if ( false === $real_path ) {
        continue;
    }

    $real_path = wp_normalize_path( $real_path );

    if ( strpos( $real_path, $snippets_realpath ) !== 0 ) {
        continue;
    }

    include_once $real_path;
}